def test_r2_distinct_permutations_with_r():
    import more_itertools as mi
    result = sorted(mi.distinct_permutations('aba', 2))
    assert result == [('a', 'a'), ('a', 'b'), ('b', 'a')]

def test_r2_one_returns_single_item():
    import more_itertools as mi
    assert mi.one([42]) == 42

def test_r2_one_raises_without_exactly_one():
    import more_itertools as mi
    for values in ([], [1, 2]):
        try:
            mi.one(values)
        except ValueError:
            pass
        else:
            raise AssertionError('expected ValueError')

def test_r2_strictly_n_exact_and_errors():
