def test_r3_is_sorted_strict_reverse():
    import more_itertools as mi
    assert mi.is_sorted([3, 2, 1], reverse=True, strict=True) is True
    assert mi.is_sorted([3, 2, 2], reverse=True, strict=True) is False

def test_r3_sample_available_for_sampling():
    import more_itertools as mi
    result = mi.sample(range(100), 5)
    assert len(result) == 5
    assert len(set(result)) == 5
    assert all(0 <= x < 100 for x in result)
